import{_ as a,o as e,c as s,ao as i}from"./chunks/framework.wWbRih9R.js";const g=JSON.parse('{"title":"The Dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"dashboard.md","filePath":"dashboard.md","lastUpdated":null}'),n={name:"dashboard.md"};function l(o,t,r,h,d,p){return e(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="The-Dashboard" tabindex="-1">The Dashboard <a class="header-anchor" href="#The-Dashboard" aria-label="Permalink to &quot;The Dashboard {#The-Dashboard}&quot;">​</a></h1><p><code>dashboard(path)</code> launches an interactive web dashboard for exploring climate simulation outputs (anything readable by <code>ClimaAnalysis.SimDir</code>) and benchmarking them against gridded observations.</p><h2 id="Quick-start" tabindex="-1">Quick start <a class="header-anchor" href="#Quick-start" aria-label="Permalink to &quot;Quick start {#Quick-start}&quot;">​</a></h2><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ClimaViz</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># A single output folder (e.g. a ClimaLand or ClimaAtmos run):</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">dashboard</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;path/to/output/&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># A ClimaCoupler run (clima_atmos/, clima_land/, … subfolders):</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">dashboard</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;path/to/coupler_output/&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; coupled </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># On HPC, serve on 0.0.0.0:8080 for SSH port forwarding:</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">dashboard</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;path/to/output/&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; HPC </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Then open <code>http://localhost:8080/</code> in your browser (see <a href="/ClimaViz.jl/previews/PR68/index#Using-from-HPC">Using from HPC</a> for port forwarding).</p><h2 id="What-you-see" tabindex="-1">What you see <a class="header-anchor" href="#What-you-see" aria-label="Permalink to &quot;What you see {#What-you-see}&quot;">​</a></h2><p>The dashboard is a single page with a menu column and four linked panels:</p><ul><li><p><strong>2D map</strong> of the selected variable. Click anywhere to select a location — the time series and vertical profile follow.</p></li><li><p><strong>Bias map</strong> (simulation − observation), shown whenever the selected variable has a registered observation. The observation is regridded onto the simulation grid; the colorbar is symmetric and stable across time.</p></li><li><p><strong>Time series</strong> at the selected location (or a global mean, see below), with the observation overlaid when available.</p></li><li><p><strong>Vertical profile</strong> for variables with a height dimension; for 2D variables this panel is replaced by a <strong>benchmark metrics table</strong> (Sim mean, Obs mean, Bias, RMSE for the selected time frame).</p></li></ul><h2 id="The-menus" tabindex="-1">The menus <a class="header-anchor" href="#The-menus" aria-label="Permalink to &quot;The menus {#The-menus}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Menu</th><th style="text-align:right;">What it does</th></tr></thead><tbody><tr><td style="text-align:right;"><strong>Component</strong></td><td style="text-align:right;">(coupled mode only) Switch between <code>atmos</code>, <code>land</code>, <code>ocean</code>, <code>seaice</code>. Components with no output are hidden.</td></tr><tr><td style="text-align:right;"><strong>Variable</strong></td><td style="text-align:right;">Searchable list of every variable found in the output.</td></tr><tr><td style="text-align:right;"><strong>Aggregation</strong></td><td style="text-align:right;">Re-bin the time axis on the fly: native resolution (e.g. Monthly), Seasonal, or Annual.</td></tr><tr><td style="text-align:right;"><strong>Time series</strong></td><td style="text-align:right;"><code>Local (click map)</code> — the clicked location — or a global mean. Clicking a map switches back to Local.</td></tr><tr><td style="text-align:right;"><strong>Time</strong></td><td style="text-align:right;">Slider through the (aggregated) time axis. The ▶ button animates it; the speed slider sets the frame delay.</td></tr><tr><td style="text-align:right;"><strong>Height</strong></td><td style="text-align:right;">Level selection for 3D variables.</td></tr><tr><td style="text-align:right;"><strong>Model summary</strong></td><td style="text-align:right;">Opens the model performance summary overlay (see below).</td></tr><tr><td style="text-align:right;"><strong>Dark Mode</strong></td><td style="text-align:right;">Toggles the page theme.</td></tr></tbody></table><h3 id="Global-means-and-spatial-masks" tabindex="-1">Global means and spatial masks <a class="header-anchor" href="#Global-means-and-spatial-masks" aria-label="Permalink to &quot;Global means and spatial masks {#Global-means-and-spatial-masks}&quot;">​</a></h3><p>&quot;Global&quot; statistics — the global time series, the metrics table and the model summary — use an area-weighted mean restricted to where the component&#39;s fields are meaningful:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Component</th><th style="text-align:right;">Mask</th><th style="text-align:right;">Menu label</th></tr></thead><tbody><tr><td style="text-align:right;">land (and plain single-folder runs)</td><td style="text-align:right;">ocean-masked (land only)</td><td style="text-align:right;"><code>Global (land mean)</code></td></tr><tr><td style="text-align:right;">atmos</td><td style="text-align:right;">none (full globe)</td><td style="text-align:right;"><code>Global</code></td></tr><tr><td style="text-align:right;">ocean / seaice</td><td style="text-align:right;">land-masked (ocean only)</td><td style="text-align:right;"><code>Global (ocean mean)</code></td></tr></tbody></table><h2 id="Benchmarks" tabindex="-1">Benchmarks <a class="header-anchor" href="#Benchmarks" aria-label="Permalink to &quot;Benchmarks {#Benchmarks}&quot;">​</a></h2><p>Variables with a registered observation get the bias map, the metrics table, an observation line in the time series, and a row in the model summary. The built-in registry (<a href="/ClimaViz.jl/previews/PR68/api#ClimaViz.default_obs"><code>default_obs</code></a>) covers:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Simulation variable</th><th style="text-align:right;">Observation product</th><th style="text-align:right;">Notes</th></tr></thead><tbody><tr><td style="text-align:right;"><code>lhf</code>, <code>shf</code>, <code>lwu</code>, <code>swu</code></td><td style="text-align:right;">ERA5 monthly surface fluxes</td><td style="text-align:right;">ClimaLand names</td></tr><tr><td style="text-align:right;"><code>hfls</code>, <code>hfss</code>, <code>rlus</code>, <code>rsus</code></td><td style="text-align:right;">ERA5 monthly surface fluxes</td><td style="text-align:right;">same fields, ClimaAtmos/CMIP names</td></tr><tr><td style="text-align:right;"><code>nee</code></td><td style="text-align:right;">CarbonTracker CT2022</td><td style="text-align:right;">inversion-derived, 2002–2020</td></tr><tr><td style="text-align:right;"><code>gpp</code></td><td style="text-align:right;">GOSIF-GPP v2</td><td style="text-align:right;"></td></tr><tr><td style="text-align:right;"><code>er</code></td><td style="text-align:right;">CarbonTracker + GOSIF residual</td><td style="text-align:right;"></td></tr><tr><td style="text-align:right;"><code>hr</code></td><td style="text-align:right;">Hashimoto 2015</td><td style="text-align:right;"></td></tr></tbody></table><p>Carbon fluxes are displayed in <code>g C m^-2 day^-1</code> (converted from the model&#39;s <code>mol CO2 m^-2 s^-1</code>). All observation data ships as lazy artifacts — nothing to download manually.</p><h3 id="Custom-observations" tabindex="-1">Custom observations <a class="header-anchor" href="#Custom-observations" aria-label="Permalink to &quot;Custom observations {#Custom-observations}&quot;">​</a></h3><p>Pass your own registry via the <code>obs</code> keyword: a <code>Dict{String, Function}</code> mapping a simulation short name to a loader. Each loader receives the simulation&#39;s start date and returns a <code>ClimaAnalysis.OutputVar</code> (units must match the displayed simulation units). Set <code>attributes[&quot;obs_source&quot;]</code> on the returned variable to control the product name shown in the legend, bias title and metrics table:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">my_obs </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Dict{String, Function}</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;ts&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> start_date </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> begin</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        var </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ClimaAnalysis</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">OutputVar</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;my_obs_ts.nc&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        var</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">attributes[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;obs_source&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;MyProduct&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        var</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    end</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">dashboard</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(path; obs </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> merge</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">default_obs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(), my_obs))</span></span></code></pre></div><h2 id="Model-summary" tabindex="-1">Model summary <a class="header-anchor" href="#Model-summary" aria-label="Permalink to &quot;Model summary {#Model-summary}&quot;">​</a></h2><p>The <strong>Model summary</strong> button opens an overlay with one row per benchmarked variable and one column per season (All-time / DJF / MAM / JJA / SON). Each cell shows the global RMSE (and bias) against the observation over the whole simulation period, color-coded by RMSE relative to the observed mean (green ≤ 25 %, red ≥ 125 %) — the whole model&#39;s performance in one image.</p><p>The summary is computed once per component and persisted in the cache; reopening it is instant. Start the server with <code>precompute = true</code> to warm it up front.</p><h2 id="ClimaCoupler-outputs-coupled-true" tabindex="-1">ClimaCoupler outputs (<code>coupled = true</code>) <a class="header-anchor" href="#ClimaCoupler-outputs-coupled-true" aria-label="Permalink to &quot;ClimaCoupler outputs (\`coupled = true\`) {#ClimaCoupler-outputs-coupled-true}&quot;">​</a></h2><p>A ClimaCoupler run writes one diagnostics folder per component:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>coupler_output/</span></span>
<span class="line"><span>├── clima_atmos/    # *_1M_*.nc monthly diagnostics (+ restarts, configs)</span></span>
<span class="line"><span>├── clima_land/</span></span>
<span class="line"><span>├── clima_ocean/</span></span>
<span class="line"><span>└── clima_seaice/</span></span></code></pre></div><p>With <code>coupled = true</code> the dashboard discovers these folders and adds the Component menu. Details handled for you:</p><ul><li><p>The atmos component is restricted to its monthly (<code>_1M_</code>) native-grid diagnostics (instantaneous fields and pressure-level variants are skipped).</p></li><li><p>Components whose files lack a <code>start_date</code> attribute (possible for land) inherit the atmos start date.</p></li><li><p>Each component gets its own benchmark cache and spatial mask.</p></li><li><p>All components are assumed to share the diagnostic lon/lat grid (which is how ClimaCoupler writes them).</p></li></ul><h2 id="Performance-and-caching" tabindex="-1">Performance and caching <a class="header-anchor" href="#Performance-and-caching" aria-label="Permalink to &quot;Performance and caching {#Performance-and-caching}&quot;">​</a></h2><p>The slow part of benchmarking — regridding observations onto the simulation grid and computing ocean-masked metrics — is cached persistently in <code>&lt;output&gt;/.climaviz_cache/</code> (one per component in coupled mode). Raw simulation fields are always read lazily and are never cached.</p><ul><li><p>First visit to a variable computes its benchmark in the background (a progress bar shows the status); everything after that is instant, including switching back to previously viewed variables within a session.</p></li><li><p><a href="/ClimaViz.jl/previews/PR68/api#ClimaViz.precompute_dashboard_cache"><code>precompute_dashboard_cache</code></a> warms every cacheable entry up front; <code>dashboard(path; precompute = true)</code> does this (plus the model summary) before serving. Recommended for long-lived deployments:</p></li></ul><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">dashboard</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;path/to/output/&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; HPC </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, precompute </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>The cache is fingerprinted against the source NetCDF files (size + mtime), so regenerating the simulation output invalidates it automatically. It is safe to delete <code>.climaviz_cache/</code> at any time. If the output folder is a git repository, add <code>.climaviz_cache/</code> to its <code>.gitignore</code>.</p>`,33)])])}const k=a(n,[["render",l]]);export{g as __pageData,k as default};
